package net.civeira.phylax.feature.observe.observabilityconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.ObservabilityConfig;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.valueobject.LabelDenylistVO;

class LabelDenylistValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of label denylist of observability config")
  void test_label_denylist_value_holder_assign_plain_value() {
    Object holder = new Object();
    LabelDenylistValueHolder<Object> value = new LabelDenylistValueHolder<>(holder);
    Assertions.assertSame(holder, value.labelDenylist("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getLabelDenylistValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getLabelDenylist().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.labelDenylistNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getLabelDenylistValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getLabelDenylist().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of label denylist of observability config")
  void test_label_denylist_value_holder_assign_value_object() {
    Object holder = new Object();
    LabelDenylistValueHolder<Object> value = new LabelDenylistValueHolder<>(holder);
    LabelDenylistVO vo = LabelDenylistVO.from("one");
    Assertions.assertFalse(value.getLabelDenylistValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.labelDenylist(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getLabelDenylistValue().orElseThrow());
    Assertions.assertSame(holder, value.labelDenylist(Optional.empty()));
    Assertions.assertFalse(value.getLabelDenylistValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.labelDenylist(Optional.of(vo)));
    Assertions.assertSame(vo, value.getLabelDenylistValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of label denylist of observability config against the original")
  void test_label_denylist_value_holder_read() {
    Object holder = new Object();
    LabelDenylistValueHolder<Object> value = new LabelDenylistValueHolder<>(holder);
    LabelDenylistVO vo = LabelDenylistVO.from("one");
    LabelDenylistVO other = LabelDenylistVO.from("one");
    ObservabilityConfig original = Mockito.mock(ObservabilityConfig.class);
    Mockito.when(original.getLabelDenylistValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readLabelDenylist(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readLabelDenylist(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.labelDenylist(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readLabelDenylist(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readLabelDenylist(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of label denylist of observability config")
  void test_label_denylist_value_holder_unset() {
    Object holder = new Object();
    LabelDenylistValueHolder<Object> value = new LabelDenylistValueHolder<>(holder);
    LabelDenylistVO vo = LabelDenylistVO.from("one");
    value.labelDenylist(vo);
    Assertions.assertSame(holder, value.unsetLabelDenylistIfMatches("labelDenylist_other"));
    Assertions.assertTrue(value.getLabelDenylistValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetLabelDenylistIfMatches("labelDenylist"));
    Assertions.assertFalse(value.getLabelDenylistValue().isPresent(),
        "The field name must clear the value");
    value.labelDenylist(vo);
    Assertions.assertSame(holder, value.unsetLabelDenylist());
    Assertions.assertFalse(value.getLabelDenylistValue().isPresent(), "Unset must clear the value");
  }
}
